text.value:
@concat(
    'UPDATE water.lastmodifiles SET lastmodifeddate = ',
    if(
        equals(last(split(item().FileName,'/')),'products.csv'),
        'SYSUTCDATETIME()',
        concat(
            '''',
            string(
                if(
                    equals(last(split(item().FileName,'/')),'customers.csv'),
                    activity('source_files').output.firstRow.signup_date,
                    if(
                        equals(last(split(item().FileName,'/')),'orders.csv'),
                        activity('source_files').output.firstRow.order_date,
                        activity('source_files').output.firstRow.payment_date
                    )
                )
            ),
            ''''
        )
    ),
    ', soruce_count = ',
    string(activity('copy data1').output.rowsRead),
    ', dst_count = ',
    string(activity('copy data1').output.rowsCopied),
    ', total_count = ISNULL(total_count,0) + ',
    string(activity('copy data1').output.rowsCopied),
    ' WHERE Tablename = ''',
    replace(last(split(item().FileName,'/')),'.csv',''),
    ''';'
)

